CREATE TABLE note (
  id         int  PRIMARY KEY,
  post_id    int  NOT NULL REFERENCES post(id)   ON DELETE CASCADE,    -- part of the post
  author_id  int           REFERENCES author(id) ON DELETE SET NULL,   -- survives its author
  body       text NOT NULL
);

